  item: PetRegisteredFollowUp,
): Promise<{ launched: boolean; text: string; taskId?: string }> {
  if (item.intent !== "resume" || !item.sourceSessionId)
    throw new Error("invalid resume follow-up");
  const result = await this.withManagerTurn(() =>
    this.dispatchNow({
      type: "chat",
      hostWake: item,
      clientMessageId: `pet-followup-${item.id}-${item.revision}`,

const [segmentTurn, worldExtrasRaw, personalization] = await Promise.all([
  this.options.segmentController?.beginTurn(command.clientMessageId),
  this.options.worldContext?.(contextInput),
  this.currentPersonalization(),
]);
const carryoverBrief = segmentTurn?.carryoverBrief;
const worldExtras = worldExtrasRaw ?? {};

  clientMessageId: command.clientMessageId,
  ...(segmentTurn?.closedSegment && command.clientMessageId
    ? {
        archiveBeforeCurrentTurn: {
          ...(segmentTurn.closedSegment.closingBoundaryMessageId &&
          !segmentTurn.archiveSummary
            ? {
                fromClientMessageId: segmentTurn.closedSegment.closingBoundaryMessageId,
              }
            : {}),
          segmentId: segmentTurn.closedSegment.segmentId,
          ...(segmentTurn.archiveSummary ? { summary: segmentTurn.archiveSummary } : {}),
        },
      }
    : {}),
}).finally(() => {
  if (!segmentTurn?.closedSegment?.nextBoundaryMessageId) return;
  // Journal/memory extraction is intentionally background work. It
  // starts only after agent/run has settled, so its end anchor is no
  // longer racing the transcript append.
  void this.options.segmentController
    ?.completeSegmentClosure(segmentTurn.closedSegment)
    .catch(() => undefined);
});

private async runBeginTurn(clientMessageId?: string): Promise<PetSegmentTurnStart | undefined> {
  const now = this.options.now();
  const lastInteractionAt = this.options.store.lastInteractionAt();
  const manualClear = this.manualClearPending;
  // The very first interaction has no preceding segment to close, so it only
  // establishes the interaction baseline — never a visible boundary. Without
  // this guard `shouldStartNewSegment(0, now, idleMs)` is always true and the
  // user's first message would render a bare "new topic" divider (with no
  // brief, since work memory is still empty). Only a *later* turn that crosses
  // the idle gap opens a visible new segment.
  const isFirstInteraction = lastInteractionAt === 0;
  const openNew =
    manualClear ||
    (!isFirstInteraction &&
      shouldStartNewSegment({ lastInteractionAt, now, idleMs: this.options.idleMs }));

// Capture the segment that is about to close before we append the new one.
const closing = this.options.store.activeSegment();
const closedSegment = closing
  ? {
      segmentId: closing.id,
      ...(closing.boundaryBeforeMessageId
        ? { closingBoundaryMessageId: closing.boundaryBeforeMessageId }
        : {}),
      ...(clientMessageId ? { nextBoundaryMessageId: clientMessageId } : {}),
      startedAt: closing.startedAt,
      endedAt: now,
    }
  : undefined;
const brief = manualClear ? "" : this.buildBrief();
const briefText = brief.length > 0 ? brief : undefined;
await this.options.store.openSegment({
  id: `seg-${randomUUID()}`,
  startedAt: now,
  ...(clientMessageId ? { boundaryBeforeMessageId: clientMessageId } : {}),
  ...(briefText ? { brief: briefText } : {}),
});
await this.options.store.setLastInteractionAt(now);
if (manualClear) this.manualClearPending = false;
return {
  ...(briefText ? { carryoverBrief: briefText } : {}),
  ...(closedSegment ? { closedSegment } : {}),
  ...(manualClear ? { archiveSummary: PET_MANUAL_CLEAR_ARCHIVE_SUMMARY } : {}),

