async backfill(segments, now) {
  // Every segment except the active (last) one has settled. Skip those the
  // journal already recorded; the last segment stays open until its own
  // boundary closes it.
  if (segments.length <= 1) return;
  await deps.journal.load().catch(() => undefined);
  const recorded = deps.journal.recordedSegmentIds();
  const settled = segments.slice(0, -1);
  for (let index = 0; index < settled.length; index += 1) {
    const segment = settled[index]!;
    if (recorded.has(segment.id)) continue;
    const next = segments[index + 1];
    try {
      const result = await this.close({
        segmentId: segment.id,
        ...(segment.boundaryBeforeMessageId
          ? { closingBoundaryMessageId: segment.boundaryBeforeMessageId }
          : {}),
        ...(next?.boundaryBeforeMessageId
          ? { nextBoundaryMessageId: next.boundaryBeforeMessageId }
          : {}),
        startedAt: segment.startedAt,
        endedAt: next?.startedAt ?? now,
      });
      // Backfill does NOT archive: the range may already have been archived
      // in the previous run, and re-archiving a shifted window would corrupt
      // live context. It only recovers the missing journal + memory record.

export function locateClosureWindow(
  messages: readonly ClosureMessage[],
  closingBoundaryMessageId: string | undefined,
  nextBoundaryMessageId: string | undefined,
): ClosureWindow | null {
  const start = closingBoundaryMessageId
    ? indexOfClientMessage(messages, closingBoundaryMessageId)
    : 0;
  if (start < 0) return null;
  const end =
    nextBoundaryMessageId !== undefined
      ? indexOfClientMessage(messages, nextBoundaryMessageId)
      : messages.length;
  if (end < 0 || end <= start) return null;
  return { messages: messages.slice(start, end), range: { start, end } };

if (entries.size >= MAX_ENTRIES) throw new Error("follow-up registry is full");
const at = this.timestamp();
if (snapshot.wakeAt <= at) throw new Error("follow-up wakeAt must be in the future");
const row: PetRegisteredFollowUp = {
  id: `registered-followup-${createHash("sha256").update(operationKey).digest("hex").slice(0, 24)}`,
  ...snapshot,
  missedPolicy: snapshot.missedPolicy ?? "fire-once",
  catchUpUntil: snapshot.catchUpUntil ?? snapshot.wakeAt + 24 * 60 * 60 * 1000,
  registrationKey: key,
  revision: 1,
  status: "open",
  createdAt: at,
  updatedAt: at,
  wake: { revision: 1, status: "scheduled" },
};
entries.set(row.id, row);
return row;

async openSegment(segment: PetTopicSegment): Promise<void> {
  return this.enqueueMutation(async () => {
    const previous = this.segments;
    this.segments = [...this.segments, segment].slice(-MAX_SEGMENTS);
    try {
      await this.enqueuePersist();
    } catch (error) {
      this.segments = previous;
      throw error;
    }
  });

private enqueuePersist(): Promise<void> {
  const snapshot: PersistedWorkMemory = {
    version: 1,
    lastInteractionAt: this.last,
    ...(this.segments.length > 0 ? { segments: [...this.segments] } : {}),
    entries: [...this.entriesList],
  };
  const persisted = this.writeQueue.then(() => this.persist(snapshot));
  this.writeQueue = persisted.catch(() => undefined);
  return persisted;
